def hit_seconds(n_tokens, kv_bytes_per_token, bandwidth, t0):
    # fixed engine cost, then bytes over the wire
    return t0 + n_tokens * kv_bytes_per_token / bandwidth

def recompute_seconds(n_tokens, tokens_per_second):
    # prefill the prompt again on the GPU
    return n_tokens / tokens_per_second

def worth_fetching(n_tokens, s, bandwidth, t0, r):
    if bandwidth <= s * r:        # below B* = sR every hit loses
        return False
    return hit_seconds(n_tokens, s, bandwidth, t0) < recompute_seconds(n_tokens, r)

# Even with infinite bandwidth a hit still costs t0, so any prompt
# shorter than t0 * r tokens is cheaper to recompute.
